//! Runs every Mammoth program under `tests/programs` and `examples`, verifying the
//! generated bytecode with `-Xverify:all` and comparing standard output with the
//! matching `.out` file. Programs in `tests/errors` must fail to compile with the
//! message given on their first line as `// error: <text>`.

use std::{
    fs,
    path::{Path, PathBuf},
    process::{Command, Stdio},
    sync::atomic::{AtomicUsize, Ordering},
    thread,
};

static NEXT_DIR: AtomicUsize = AtomicUsize::new(0);

fn compiler() -> &'static str {
    env!("CARGO_BIN_EXE_mammoth")
}

fn scratch() -> PathBuf {
    let dir = std::env::temp_dir().join(format!(
        "mammoth-test-{}-{}",
        std::process::id(),
        NEXT_DIR.fetch_add(1, Ordering::SeqCst)
    ));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    dir
}

fn normalize(text: &str) -> String {
    text.replace("\r\n", "\n").trim_end().to_owned()
}

fn run_program(source: &Path, expected: &Path) -> Result<(), String> {
    let dir = scratch();
    let compiled = Command::new(compiler())
        .arg(source)
        .arg(&dir)
        .output()
        .map_err(|error| error.to_string())?;
    if !compiled.status.success() {
        let _ = fs::remove_dir_all(&dir);
        return Err(format!(
            "{}: compile failed\n{}",
            source.display(),
            String::from_utf8_lossy(&compiled.stderr)
        ));
    }
    let entry = fs::read_to_string(source)
        .unwrap()
        .lines()
        .find_map(|line| line.trim().strip_prefix("module "))
        .map_or_else(|| "Main".to_owned(), |module| module.trim().to_owned());
    let input = source.with_extension("in");
    let mut child = Command::new("java")
        .args(["-Xverify:all", "-cp"])
        .arg(&dir)
        .arg(&entry)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|error| error.to_string())?;
    {
        use std::io::Write;
        let mut stdin = child.stdin.take().unwrap();
        if let Ok(bytes) = fs::read(&input) {
            stdin.write_all(&bytes).unwrap();
        }
    }
    let output = child
        .wait_with_output()
        .map_err(|error| error.to_string())?;
    let _ = fs::remove_dir_all(&dir);
    let stdout = normalize(&String::from_utf8_lossy(&output.stdout));
    let stderr = String::from_utf8_lossy(&output.stderr);
    let wanted = normalize(&fs::read_to_string(expected).unwrap_or_default());
    if stderr.contains("VerifyError") || stderr.contains("ClassFormatError") {
        return Err(format!("{}: invalid bytecode\n{stderr}", source.display()));
    }
    if !output.status.success() {
        return Err(format!(
            "{}: execution failed ({})\n{stderr}",
            source.display(),
            output.status
        ));
    }
    if stdout != wanted {
        return Err(format!(
            "{}: output mismatch\n--- expected\n{wanted}\n--- actual\n{stdout}\n--- stderr\n{stderr}",
            source.display()
        ));
    }
    Ok(())
}

fn check_error(source: &Path) -> Result<(), String> {
    let text = fs::read_to_string(source).unwrap();
    let wanted = text
        .lines()
        .next()
        .and_then(|line| line.trim().strip_prefix("// error:"))
        .ok_or_else(|| format!("{}: missing // error: line", source.display()))?
        .trim()
        .to_owned();
    let dir = scratch();
    let output = Command::new(compiler())
        .arg(source)
        .arg(&dir)
        .output()
        .map_err(|error| error.to_string())?;
    let _ = fs::remove_dir_all(&dir);
    let stderr = String::from_utf8_lossy(&output.stderr);
    if output.status.success() {
        return Err(format!("{}: compiled but should fail", source.display()));
    }
    if !stderr.contains(&wanted) {
        return Err(format!(
            "{}: wrong error\n--- expected to contain\n{wanted}\n--- actual\n{stderr}",
            source.display()
        ));
    }
    Ok(())
}

fn files(dir: &str) -> Vec<PathBuf> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join(dir);
    let mut files: Vec<_> = fs::read_dir(&root)
        .map(|entries| {
            entries
                .filter_map(|entry| entry.ok().map(|entry| entry.path()))
                .filter(|path| path.extension().is_some_and(|ext| ext == "mam"))
                .collect()
        })
        .unwrap_or_default();
    files.sort();
    files
}

fn run_all(jobs: Vec<Box<dyn FnOnce() -> Result<(), String> + Send>>) {
    let total = jobs.len();
    let jobs = std::sync::Mutex::new(jobs);
    let failures = std::sync::Mutex::new(Vec::new());
    thread::scope(|scope| {
        for _ in 0..8 {
            scope.spawn(|| {
                loop {
                    let job = jobs.lock().unwrap().pop();
                    let Some(job) = job else { break };
                    if let Err(message) = job() {
                        failures.lock().unwrap().push(message);
                    }
                }
            });
        }
    });
    let failures = failures.into_inner().unwrap();
    if !failures.is_empty() {
        panic!(
            "{} of {total} checks failed:\n\n{}",
            failures.len(),
            failures.join("\n\n")
        );
    }
}

#[test]
fn programs_produce_expected_output() {
    let mut jobs: Vec<Box<dyn FnOnce() -> Result<(), String> + Send>> = Vec::new();
    for source in files("tests/programs") {
        let expected = source.with_extension("out");
        jobs.push(Box::new(move || run_program(&source, &expected)));
    }
    let expected_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/examples");
    for source in files("examples") {
        let expected = expected_dir
            .join(source.file_name().unwrap())
            .with_extension("out");
        if expected.exists() {
            jobs.push(Box::new(move || run_program(&source, &expected)));
        }
    }
    run_all(jobs);
}

#[test]
fn invalid_programs_report_errors() {
    let mut jobs: Vec<Box<dyn FnOnce() -> Result<(), String> + Send>> = Vec::new();
    for source in files("tests/errors") {
        jobs.push(Box::new(move || check_error(&source)));
    }
    run_all(jobs);
}

/// Truncates every program at several points. The compiler must report an
/// error or succeed, never panic or hang, whatever the input.
fn check_truncations(source: &Path) -> Result<(), String> {
    let text = fs::read_to_string(source).unwrap();
    let dir = scratch();
    let cut = dir.join("cut.mam");
    let mut result = Ok(());
    for step in 1..8 {
        let mut end = text.len() * step / 8;
        while !text.is_char_boundary(end) {
            end -= 1;
        }
        fs::write(&cut, &text[..end]).unwrap();
        let mut child = Command::new(compiler())
            .arg(&cut)
            .arg(dir.join("out"))
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|error| error.to_string())?;
        let started = std::time::Instant::now();
        let status = loop {
            if let Some(status) = child.try_wait().map_err(|error| error.to_string())? {
                break status;
            }
            if started.elapsed() > std::time::Duration::from_secs(20) {
                let _ = child.kill();
                break child.wait().map_err(|error| error.to_string())?;
            }
            thread::sleep(std::time::Duration::from_millis(5));
        };
        let mut stderr = String::new();
        if let Some(mut pipe) = child.stderr.take() {
            use std::io::Read;
            let _ = pipe.read_to_string(&mut stderr);
        }
        if started.elapsed() > std::time::Duration::from_secs(20) {
            result = Err(format!("{} cut at {end}: compiler hung", source.display()));
            break;
        }
        if !matches!(status.code(), Some(0 | 1)) || stderr.contains("panicked") {
            result = Err(format!(
                "{} cut at {end}: compiler crashed ({status})\n{stderr}",
                source.display()
            ));
            break;
        }
    }
    let _ = fs::remove_dir_all(&dir);
    result
}

#[test]
fn truncated_programs_fail_cleanly() {
    let mut jobs: Vec<Box<dyn FnOnce() -> Result<(), String> + Send>> = Vec::new();
    for source in files("tests/programs").into_iter().chain(files("examples")) {
        jobs.push(Box::new(move || check_truncations(&source)));
    }
    run_all(jobs);
}
